/**
 * AV1 inverse quantization matrices, packed with a small LZ4-block decoder.
 *
 * The 15 luma/chroma matrix sets are normative codec tables. Transform sizes
 * above 32 coefficients in either dimension reuse the corresponding capped
 * matrix, as required by AV1's coefficient coding.
 */
const PACKED = ''
const MATRIX_SET_SIZE = 3344
const MATRIX_DATA_SIZE = 15 * 2 * MATRIX_SET_SIZE

const TX_OFFSETS = [
  0, 16, 80, 336, 336,
  1360, 1392, 1424, 1552, 1680, 2192, 336, 336, 2704, 2768, 2832, 3088, 1680, 2192,
] as const
const TX_LENGTHS = [
  16, 64, 256, 1024, 1024,
  32, 32, 128, 128, 512, 512, 1024, 1024, 64, 64, 256, 256, 512, 512,
] as const

function readExtendedLength(bytes: string, position: { value: number }, length: number): number {
  if (length !== 15)
    return length
  let next: number
  do {
    next = bytes.charCodeAt(position.value++)
    length += next
  } while (next === 255)
  return length
}

function unpackMatrices(encoded: string): Uint8Array {
  const bytes = atob(encoded)
  const output = new Uint8Array(MATRIX_DATA_SIZE)
  const source = { value: 0 }
  let destination = 0

  while (source.value < bytes.length) {
    const token = bytes.charCodeAt(source.value++)
    const literalLength = readExtendedLength(bytes, source, token >> 4)
    for (let i = 0; i < literalLength; i++)
      output[destination++] = bytes.charCodeAt(source.value++)
    if (source.value >= bytes.length)
      break

    const offset = bytes.charCodeAt(source.value) | bytes.charCodeAt(source.value + 1) << 8
    source.value += 2
    const matchLength = readExtendedLength(bytes, source, token & 15) + 4
    for (let i = 0; i < matchLength; i++)
      output[destination] = output[destination++ - offset]
  }

  if (destination !== MATRIX_DATA_SIZE)
    throw new Error('ts-avif: corrupt embedded quantization matrix data')
  return output
}

const matrixCache: { value: Uint8Array | null } = { value: null }

/**
 * Return the inverse quantization matrix for one transform, or null for the
 * flat level (15). Plane 0 selects luma; planes 1/2 share chroma matrices.
 */
export function getQuantMatrix(level: number, plane: number, tx: number): Uint8Array | null {
  if (level === 15)
    return null
  if (level < 0 || level > 15 || tx < 0 || tx >= TX_OFFSETS.length)
    throw new Error(`ts-avif: invalid quantization matrix level/transform (${level}/${tx})`)
  matrixCache.value ??= unpackMatrices(PACKED)
  const matrices = matrixCache.value
  const base = (level * 2 + (plane === 0 ? 0 : 1)) * MATRIX_SET_SIZE + TX_OFFSETS[tx]
  return matrices.subarray(base, base + TX_LENGTHS[tx])
}
